<?php get_header(); while(have_posts()): the_post();
$id=get_the_ID();
$content=apply_filters('the_content',get_the_content());
$toc=[];
$content=preg_replace_callback('~<h2([^>]*)>(.*?)</h2>~s',function($m) use (&$toc) { $title=wp_strip_all_tags($m[2]); $anchor='lectura-'.(count($toc)+1); $toc[]=[$anchor,$title]; return '<h2 id="'.$anchor.'">'.$m[2].'</h2>'; },$content);
?>
<main id="contenido"><section class="cv-article-hero"><div class="cv-wrap"><?php cv_breadcrumbs(); ?><div class="cv-article-heading"><p class="cv-eyebrow">Cuaderno Vocal · <?php echo esc_html(implode(' · ',wp_get_post_categories($id,['fields'=>'names']))); ?></p><h1><?php the_title(); ?></h1><p class="cv-lead"><?php echo esc_html(get_the_excerpt()); ?></p><div class="cv-article-meta"><span>Clínica Vocal · Contenido divulgativo</span><time datetime="<?php echo esc_attr(get_the_date('c')); ?>"><?php echo esc_html(get_the_date('j F Y')); ?></time><span><?php echo cv_reading_time($id); ?> min de lectura</span></div></div></div></section>
<div class="cv-wrap cv-article-layout"><aside class="cv-article-sidebar"><h2>En esta lectura</h2><nav aria-label="Índice del artículo"><ol class="cv-toc"><?php foreach($toc as [$anchor,$title]) echo '<li><a href="#'.esc_attr($anchor).'">'.esc_html($title).'</a></li>'; ?></ol></nav><button class="cv-copy-link" type="button" aria-live="polite">Copiar enlace del artículo</button><p class="cv-editorial-note">Información para orientarte. Cada situación merece una valoración individual.</p></aside><article class="cv-prose"><img class="cv-article-cover" src="<?php echo esc_url(cv_asset(cv_meta('art'))); ?>" alt="" width="800" height="800"><?php echo $content; ?><p class="cv-editorial-note">Este contenido es divulgativo y no sustituye una consulta profesional. No permite establecer un diagnóstico ni indicar un tratamiento individual.</p></article></div>
<section class="cv-related"><div class="cv-wrap"><p class="cv-eyebrow">Sigue explorando</p><h2>Otras lecturas que pueden acompañarte</h2><div class="cv-article-grid"><?php $related=get_posts(['post_type'=>'post','numberposts'=>3,'post__not_in'=>[$id],'orderby'=>'date']); foreach($related as $p) cv_post_card($p->ID); ?></div></div></section>
<?php cv_cta(); ?></main><?php endwhile; get_footer(); ?>
